from pathlib import Path
p=Path('src/components/SupportLauncher.vue');s=p.read_text(encoding='utf-8')
s=s.replace('class="support-alert-toast" role="status"','class="support-alert-toast" :style="panelPosition" role="status"')
s=s.replace('class="support-launcher-panel"><header>','class="support-launcher-panel" :style="panelPosition"><header>')
s=s.replace('<div class="support-launcher-actions">','<p class="support-launcher-hint">Arrastra el botón para moverlo o usa las flechas del teclado. Puedes pegarlo al borde para ocupar menos espacio.</p><button type="button" @click="toggleDock">{{docked?\'Despegar del marco\':\'Pegar al marco\'}}</button><div class="support-launcher-actions">',1)
s=s.replace('<button v-if="!createOpen && !portalOpen" type="button" class="support-floating-button"', '<div v-if="!createOpen && !portalOpen" ref="floatControl" class="support-float-control" :class="{\'is-docked\':docked,\'is-right\':dockSide===\'right\',\'is-dragging\':dragging}" :style="floatPosition" @pointerdown="startDrag"><button type="button" class="support-floating-button" title="Arrastra para mover; pulsa para abrir soporte" @keydown="moveWithKeys"')
s=s.replace('@click="panel=!panel"','@click="togglePanel"',1)
s=s.replace('</b></button>\n <b-modal', '''</b></button><button type="button" class="support-dock-button" :aria-label="docked?'Despegar soporte del marco':'Pegar soporte al marco'" :title="docked?'Despegar del marco':'Pegar al marco'" :aria-pressed="docked?'true':'false'" @pointerdown.stop @click.stop="toggleDock">{{docked?'↗':'⇥'}}</button></div>
 <b-modal''',1)
s=s.replace("soundEnabled:false}},computed:","soundEnabled:false,floatX:0,floatY:96,docked:true,dockSide:'left',dragging:false,viewportW:window.innerWidth,viewportH:window.innerHeight}},computed:")
s=s.replace('computed:{categories()', '''computed:{floatPosition(){return {left:this.floatX+'px',top:this.floatY+'px'}},panelPosition(){const width=Math.min(360,this.viewportW-24),height=Math.min(430,this.viewportH-24);const left=Math.max(12,Math.min(this.floatX,this.viewportW-width-12));const top=this.floatY>this.viewportH/2?Math.max(12,this.floatY-height-12):Math.min(this.floatY+64,Math.max(12,this.viewportH-height-12));return {left:left+'px',top:top+'px',right:'auto',bottom:'auto',maxHeight:Math.max(100,this.viewportH-top-12)+'px'}},categories()''')
s=s.replace('mounted(){this.init();', '''mounted(){this._dragMove=e=>this.dragMove(e);this._dragEnd=e=>this.endDrag(e);this._resize=()=>this.clampPosition();window.addEventListener('pointermove',this._dragMove,{passive:false});window.addEventListener('pointerup',this._dragEnd);window.addEventListener('pointercancel',this._dragEnd);window.addEventListener('resize',this._resize);this.init();''')
s=s.replace('beforeDestroy(){clearInterval', "beforeDestroy(){this._drag=null;window.removeEventListener('pointermove',this._dragMove);window.removeEventListener('pointerup',this._dragEnd);window.removeEventListener('pointercancel',this._dragEnd);window.removeEventListener('resize',this._resize);clearInterval")
s=s.replace('this.context=data;try{','this.context=data;this.restorePosition();this.$nextTick(()=>this.clampPosition());try{',1)
s=s.replace('methods:{\n', '''methods:{
 controlSize(){const el=this.$refs.floatControl;return el?{w:el.offsetWidth,h:el.offsetHeight}:{w:this.docked?64:180,h:50}},
 clampPosition(){this.viewportW=window.innerWidth;this.viewportH=window.innerHeight;const size=this.controlSize();this.floatY=Math.max(8,Math.min(this.floatY,this.viewportH-size.h-8));this.floatX=this.docked?(this.dockSide==='right'?Math.max(0,this.viewportW-size.w):0):Math.max(8,Math.min(this.floatX,this.viewportW-size.w-8))},
 restorePosition(){try{const v=JSON.parse(localStorage.getItem('support:position:'+this.context.principal)||'null');if(v&&Number.isFinite(v.x)&&Number.isFinite(v.y)){this.floatX=v.x;this.floatY=v.y;this.docked=!!v.docked;this.dockSide=v.side==='right'?'right':'left'}}catch(e){}},
 savePosition(){if(this.context)try{localStorage.setItem('support:position:'+this.context.principal,JSON.stringify({x:this.floatX,y:this.floatY,docked:this.docked,side:this.dockSide}))}catch(e){}},
 togglePanel(){if(this._suppressClick)return;this.panel=!this.panel},
 toggleDock(){this.panel=false;this.docked=!this.docked;if(this.docked)this.dockSide=this.floatX+this.controlSize().w/2>this.viewportW/2?'right':'left';else this.floatX=this.dockSide==='right'?Math.max(8,this.viewportW-180):18;this.$nextTick(()=>{this.clampPosition();this.savePosition()})},
 startDrag(e){if(e.button!==0||e.target.closest('.support-dock-button'))return;const size=this.controlSize();this._drag={id:e.pointerId,x:e.clientX,y:e.clientY,left:this.floatX,top:this.floatY,w:size.w,h:size.h,target:e.currentTarget,moved:false}},
 dragMove(e){const d=this._drag;if(!d||d.id!==e.pointerId)return;const dx=e.clientX-d.x,dy=e.clientY-d.y;if(!d.moved&&Math.hypot(dx,dy)<6)return;if(!d.moved){d.moved=true;this.dragging=true;this.panel=false;try{d.target.setPointerCapture(e.pointerId)}catch(err){}}e.preventDefault();this.floatY=Math.max(8,Math.min(d.top+dy,window.innerHeight-d.h-8));if(this.docked){this.dockSide=e.clientX>window.innerWidth/2?'right':'left';this.floatX=this.dockSide==='right'?Math.max(0,window.innerWidth-d.w):0}else this.floatX=Math.max(8,Math.min(d.left+dx,window.innerWidth-d.w-8))},
 endDrag(e){const d=this._drag;if(!d||d.id!==e.pointerId)return;this._drag=null;this.dragging=false;if(d.moved){this._suppressClick=true;setTimeout(()=>{this._suppressClick=false},300);this.clampPosition();this.savePosition()}try{if(d.target.hasPointerCapture(e.pointerId))d.target.releasePointerCapture(e.pointerId)}catch(err){}},
 moveWithKeys(e){if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const delta=e.shiftKey?30:10;if(e.key==='ArrowUp')this.floatY-=delta;if(e.key==='ArrowDown')this.floatY+=delta;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){this.docked=false;this.floatX+=e.key==='ArrowRight'?delta:-delta}this.$nextTick(()=>{this.clampPosition();this.savePosition()})},
''',1)
# Remove the previous reserved header strip and fixed placement overrides.
lines=s.splitlines();lines=[line for line in lines if not line.startswith('.support-launcher .support-floating-button{top:14px;')];s='\n'.join(lines)+'\n'
p.write_text(s,encoding='utf-8')
p=Path('static/css/pos-layout-fix.css');s=p.read_text(encoding='utf-8');s='\n'.join(line for line in s.splitlines() if not line.startswith('.support-launcher .support-floating-button{top:14px!important;'))+'\n';p.write_text(s,encoding='utf-8')
